// Specifies the verbosity of a logging messages added to the diagnostics log
// (DkmDiagnosticsLog). To allow trivially checking if a given log level is enabled, this
// is declared as a flag enum, but with very few exceptions if any, messages should set a
// single flag.
//
// This API was introduced in Visual Studio 17 Update 8 (DkmApiVersion.VS17Update8).
DEFINE_SCOPED_ENUM(DkmLogLevel)
{
    // Reserved invalid value used to indicate that logging is disabled.
    Invalid = 0x0,
    // Log item is for an error that very unlikely to be ignorable. This is used for
    // logging items that should always be enabled. Example: important errors.
    ImportantError = 0x1,
    // Log item is important and inexpensive to produce. This is for items that should
    // automatically be enabled when Visual Studio feedback tickets are collected.
    // Example: entry points for start debugging.
    Important = 0x2,
    // Log item is generally useful, and should always be enabled for dev-level logs.
    Normal = 0x4,
    // Verbose logging of calls to all debug engine (vsdebugeng.dll) APIs.
    DebugEngineAPIMethod = 0x8,
    // Verbose logging of all error returns from debug engine (vsdebugeng.dll) APIs.
    DebugEngineAPIMethodFailure = 0x10,
    // Verbose logging of all events from underlying debug API (Win32, ICorDebug, etc).
    DebugRuntimeEvent = 0x20,
    // Verbose logging of expression evaluation operations.
    ExpressionEvaluation = 0x40,
    // Verbose logging of start debugging operations.
    StartDebugging = 0x80,
    // Verbose logging of Hot Reload operations.
    HotReload = 0x100,
    // Verbose logging of source related operations (location, source link,
    // decompilation, etc).
    Source = 0x200,
    // Verbose logging for dynamic deoptimization information.
    DynamicDeopt = 0x400
};
DEFINE_SCOPED_ENUM_FLAG_OPERATORS(DkmLogLevel_t);

// Enumeration describing the time that a memory read resolves to with respect to the
// current process time.
//
// This API was introduced in Visual Studio 15 Update 8 (DkmApiVersion.VS15Update8).
DEFINE_SCOPED_ENUM(DkmMemoryTimeFlags)
{
    // Default value. Represents 'Now' on the current thread.
    None = 0x0,
    // Describes a value read from a time in the past.
    IsPast = 0x1,
    // Describes a value read from a time in the future.
    IsFuture = 0x2,
    // Describes a memory range that has gaps in reachable memory across the lifespan of
    // the process.
    IsIncomplete = 0x4
};
DEFINE_SCOPED_ENUM_FLAG_OPERATORS(DkmMemoryTimeFlags_t);

// Flags which indicate traits of a DkmModuleInstance.
DEFINE_SCOPED_ENUM(DkmModuleFlags)
{
    // No module flags are set.
    None = 0x0,
    // Module is backed by a file. Note that this is set even in cases where the module
    // could not be resolved (dll is missing, binary could not be found while examining a
    // minidump, etc).
    FileBacked = 0x1,
    // Module is backed by a file and the debug monitor was able to open this file.
    FileResolved = 0x2,
    // Neither the module's file or memory content could be found. Debugging will be
    // impaired.
    MissingBinary = 0x4,
    // Module was relocated because it could not load at its preferred base address.
    Relocated = 0x8,
    // Optimization status for the module could be detected and the module was determined
    // to be optimized.
    Optimized = 0x10,
    // Optimization status for the module could be detected and the module was determined
    // to be unoptimized.
    Unoptimized = 0x20,
    // The module can be edited during debugging. For .NET modules this implies that the
    // CORDEBUG_JIT_ENABLE_ENC is set.
    Editable = 0x40,
    // True if this module was created by the Open Enclave DM.
    OpenEnclaveModule = 0x80,
    // True if this symbols for this module are permanently unavailable. (e.g. an ngen
    // module loaded by the native debugger).
    SymbolsUnavailable = 0x100
};
DEFINE_SCOPED_ENUM_FLAG_OPERATORS(DkmModuleFlags_t);

