        bool operator< (const DkmSHA1HashValue& rhs) const     { return CompareTo(rhs) < 0;  }
        bool operator>=(const DkmSHA1HashValue& rhs) const     { return CompareTo(rhs) >= 0; }
        bool operator<=(const DkmSHA1HashValue& rhs) const     { return CompareTo(rhs) <= 0; }

