    // Flags passed to DkmInstructionSymbol.GetBasicInfo and GetInlineFramesCount.
    //
    // This API was introduced in Visual Studio 16 RTM (DkmApiVersion.VS16RTMPreview).
    DEFINE_SCOPED_ENUM(DkmBasicSymbolInfoRequestFlags)
    {
        // No flags are set.
        None = 0x0,
        // Decoded stack frame is the top frame in the call stack.
        TopFrame = 0x1,
        // If set, DkmInstructionSymbol.GetBasicInfo should compute the count of inline
        // frames.
        ComputeInlineFrameCount = 0x2,
        // Include all inline frames. Must be used with ComputeInlineFrameCount.
        IncludeAllInlineFrames = 0x4
    };
    DEFINE_SCOPED_ENUM_FLAG_OPERATORS(DkmBasicSymbolInfoRequestFlags_t);

    // Flags for DkmProcess.LocateBinary.
    //
    // This API was introduced in Visual Studio 17 Update 10 (DkmApiVersion.VS17Update10).
    DEFINE_SCOPED_ENUM(DkmBinaryLocatorFlags)
    {
        // No additional flags are specified.
        None = 0x0,
        // If true, the binary locator should always attempt to load symbols, even if symbol
        // loading was previously cancelled, or the user must be prompted for credentials.
        // This should be used only for explicit user gestures to load the binary.
        ForceLoad = 0x1,
        // When specified, the binary locator will ignore the symbols include list when
        // deciding if the binary should be loaded when the 'Load only specified modules'
        // symbol option is enabled and when the 'Automatically load additional symbols when
        // needed' option within the 'Load only specified modules' section of the symbol
        // options page is set.
        AutomaticLoad = 0x2,
        // Indicates that the binary locator should not search symbol servers for binaries.
        LocalSourcesOnly = 0x4,
        // Indicates that the binary locator should not prompt the user to search for
        // binaries.
        NoPrompt = 0x8,
        // Indicates that the binary locator should not consider the metadata stored in the
        // process/dump when attempting to locate the binary.
        SkipOriginalLocation = 0x10,
        // Signifies that the Main Thread of the client is being blocked by a CoWait
        // mechanism during this binary load operation. This can inform the symbol locating
        // APIs for the purposes of threading.
        MainThreadInCoWait = 0x20
    };
    DEFINE_SCOPED_ENUM_FLAG_OPERATORS(DkmBinaryLocatorFlags_t);

    // Indicates the compression algorithm used for a buffer of bytes. This can be used to
    // determine which algorithm to use to decompress the bytes.
    //
    // This API was introduced in Visual Studio 15 Update 5 (DkmApiVersion.VS15Update5).
    DEFINE_SCOPED_ENUM(DkmCompressionAlgorithmId)
    {
        // The bytes are not compressed.
        None = 0,
        // The bytes were compressed using the DEFLATE algorithm.
        Deflate = 1
    };

    // Indicates how strong of a match there was between the DkmDocumentQuery and the
    // resulting DkmResolvedDocument.
    DEFINE_SCOPED_ENUM(DkmDocumentMatchStrength)
    {
        // Document matched on file name and extension, but not on any part of the path, or
        // on checksum.
        FileName = 0,
        // Document matched on file name and at least one level of directory name, but not
        // the full path nor the checksum.
        SubPath = 1,
        // Document matched on full path but not on checksum.
        FullPath = 2,
        // Document matched on checksum value in addition to at least a filename match.
        Checksum = 3,
        // Input path represented a URL for a dynamic document and the resulting document
        // exactly matched this query. This value is currently never returned from the
        // Microsoft PDB symbol provider but is reserved for future use.
        ExactURL = 4
    };

