    // Flags which indicate traits of a DkmModule object.
    //
    // This API was introduced in Visual Studio 17 Update 2 (DkmApiVersion.VS17Update2).
    DEFINE_SCOPED_ENUM(DkmModuleSymbolFlags)
    {
        // No module flags are set.
        None = 0x0,
        // Symbols were generated by decompiling the module instance.
        Decompiled = 0x1,
        // Symbols were loaded automatically when needed, such as native symbols loaded for
        // x86 stack walk.
        DeferredLoad = 0x2,
        // Symbols have the opportunity to be reloaded for a higher fidelity version of the
        // symbols, i.e. the current symbols are from decompilation or are stripped symbols.
        Reloadable = 0x4,
        // Symbols were generated by decompiling individual types within the module instance.
        PartiallyDecompiled = 0x8,
        // Symbols were generated without source information.
        Stripped = 0x10,
        // Symbols contain Source Server information.
        HasSourceServer = 0x20,
        // Symbols contain Source Link information.
        HasSourceLink = 0x40,
        // Symbols contain embedded source.
        HasEmbeddedSource = 0x80
    };
    DEFINE_SCOPED_ENUM_FLAG_OPERATORS(DkmModuleSymbolFlags_t);

