    // Flags to control frames returned during a stack walk.
    //
    // This API was introduced in Visual Studio 17 Update 3 (DkmApiVersion.VS17Update3).
    DEFINE_SCOPED_ENUM(DkmStackWalkContextFlags)
    {
        // No flags are set.
        None = 0x0,
        // Stack walker should include additional logical frames that aren't physically on
        // the stack.
        IncludeLogicalFrames = 0x1,
        // Indicates the stack walk can attempt to load symbols when modules without symbols
        // are encountered.
        LoadMissingSymbols = 0x2
    };
    DEFINE_SCOPED_ENUM_FLAG_OPERATORS(DkmStackWalkContextFlags_t);

