    // EnC availability status - whether EnC is available or it is not supported given a
    // specified reason.
    //
    // This API was introduced in Visual Studio 16 Update 1 (DkmApiVersion.VS16Update1).
    DEFINE_SCOPED_ENUM(DkmEncAvailableStatus)
    {
        // Edit and Continue is available.
        Available = 0,
        // Edit and Continue not supported due to interop debugging.
        Interop = 1,
        // Unable to edit code running in SQL server.
        SqlClr = 2,
        // Edit and Continue not supported in minidump debugging.
        Minidump = 3,
        // Edit and Continue not supported since debugger was attached to a process that does
        // not support EnC on attach.
        Attach = 4,
        // Edit and Continue not supported if the assembly has not been loaded.
        ModuleNotLoaded = 5,
        // Edit and Continue not supported if the assembly that has been modified during
        // debugging is reloaded.
        ModuleReloaded = 6,
        // Unable to edit while code is running. This is only reported if the engine version
        // does not support hot reload.
        InRunMode = 7,
        // Edit and Continue not supported if the source code on disk does not match the code
        // running in the process.
        NotBuilt = 8,
        // Edit and Continue not supported for the current engine.
        EngineMetricFalse = 9,
        // Edit and Continue in a 64-bit process requires .NET Framework version 4.5.1 or
        // higher.
        NotSupportedForClr64Version = 10,
        // Edit and Continue not supported on the current module. This is a fallback scenario
        // in case we fail to determine the exact reason the module does not support EnC.
        NotAllowedForModule = 11,
        // Edit and Continue not supported if code was optimized.
        Optimized = 12,
        // Edit and Continue not supported if assembly was loaded as domain-neutral.
        DomainNeutralAssembly = 13,
        // Edit and Continue not supported if assembly was loaded through reflection.
        ReflectionAssembly = 14,
        // Edit and Continue not supported if IntelliTrace events and call information is
        // enabled.
        IntelliTrace = 15,
        // Edit and Continue not supported on the .NET Runtime the program is running.
        NotAllowedForRuntime = 16,
        // Edit and Continue in an ARM64 process requires .NET 7 or higher.
        NotAllowedForArm64WithNetVersion = 17,
        // Edit and Continue is not supported when 'COR_ENABLE_PROFILING' environment
        // variable is set.
        NotAllowedWithCorEnvironmentVariable = 18,
        // Edit and Continue is not supported for decompiled assemblies.
        NotAllowedForDecompiledModule = 19,
        // Edit and Continue is not supported when there are no symbols associated with the
        // modified assembly.
        SymbolsNotLoaded = 20
    };

