// Contains types specific to edit and continue feature.
namespace Enc {
    // Edit and Continue availability status - whether Edit and Continue is available or it
    // is not supported given a specified reason.
    //
    // This API was introduced in Visual Studio 17 Update 5 (DkmApiVersion.VS17Update5).
    DEFINE_SCOPED_ENUM(DkmNativeEditAndContinueAvailableStatus)
    {
        // Edit and Continue is available.
        Available = 0,
        // Module has not been affected by the source.
        NotApplicable = 1,
        // An internal error occurred and Edit and Continue is not supported. Refer to the
        // error result for more details.
        InternalError = 2,
        // Edit and Continue is not supported on the target debug information format. It is
        // suggested to compile with the Edit and Continue PDB format.
        NoEditAndContinueDebugFormat = 3,
        // Edit and Continue is not supported because the state file is out of sync with the
        // PDB file. It is suggested to compile with the Enable Minimal Rebuild option.
        IdbIsOutOfSyncWithPdb = 4,
        // Edited file does not match its original path. Edit and Continue is only supported
        // for original files.
        OriginalPathMismatch = 5,
        // Edit and Continue is not supported without valid state files. This usually means
        // that a file has been missing or corrupt.
        IdbIsMissingOrCorrupt = 6,
        // Edit and Continue is not supported without incremental linking enabled.
        LinkerWithoutIncremental = 7,
        // Edit and Continue is not supported when optimizing iterations to perform identical
        // folding.
        LinkerWithOptIteration = 8,
        // Edit and Continue is not supported when optimizing functions and data that are
        // never referenced.
        LinkerWithOptReference = 9,
        // Edit and Continue is not supported when optimizing the detection of long branch
        // instructions. Only valid for ARM.
        LinkerWithOptLongBranchInstructions = 10,
        // Edit and Continue is not supported when building a windows NT kernel mode driver.
        LinkerWithDriver = 11,
        // Edit and Continue is not supported when building producing a table of the image's
        // safe exception handlers.
        LinkerWithSafeExceptionHandlers = 12,
        // Edit and Continue is not supported in the linker. This is a general error message
        // when unable to determine the cause of the linker not supported Edit and Continue.
        LinkerWithoutEditAndContinue = 13
    };

    // Native edit and continue notification.
    //
    // This API was introduced in Visual Studio 14 RTM (DkmApiVersion.VS14RTM).
    DEFINE_SCOPED_ENUM(DkmNativeEncNotify)
    {
        // Compilation starts.
        CompileStart = 0,
        // Compilation stops.
        CompileEnd = 1
    };

}; // end namespace Enc

